// And groups predicates with the AND operator between them.
func And(predicates ...predicate.BundleAbTests) predicate.BundleAbTests {
	return predicate.BundleAbTests(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.BundleAbTests) predicate.BundleAbTests {
	return predicate.BundleAbTests(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.BundleAbTests) predicate.BundleAbTests {
	return predicate.BundleAbTests(sql.NotPredicates(p))
}
